powerpagecomponent.content:
{
  "filecontent": null,
  "copy": "{% include 'cmdspp_ToastModal' %}
<section class="cmdspp-home-hero-section">
  <div class="cmdspp-home-hero-content">
    <div class="cmdspp-home-gov-badge"><img src="/cmdspp_HomeBadge"/>OFFICIAL GOVERNMENT PORTAL · SECURE &amp; VERIFIED</div>
    <h1>
      Welcome to CMdS<br />
      NextGen Provider Portal
    </h1>
    <p>Get access to all the tools you need to manage your day-to-day practice and deliver excellent service to your patients.</p>
    <div class="cmdspp-home-hero-buttons"><button id="cmdspp-home-btn-primary-id" class=" cmdspp-home-btn cmdspp-home-btn-primary">Get Registered</button><button id="cmdspp-home-btn-secondary-id" class="cmdspp-home-btn cmdspp-home-btn-secondary">Enrollment</button></div>
  </div>
</section>
<section class="cmdspp-home-services-section">
  <div class="cmdspp-home-service-card">
    <div class="cmdspp-home-service-text">
      <h3>Clinical</h3>
      <p>Manage clinical professionals and specializations</p>
      <span class="cmdspp-home-service-text-learnmore">Learn more...<span> </span></span>
    </div>
    <img src="/cmdspp_clinicdoctor" />
  </div>
  <div class="cmdspp-home-service-card">
    <div class="cmdspp-home-service-text">
      <h3>Ambulance / EMS</h3>
      <p>Register and verify EMS personnel and ambulance services</p>
      <span class="cmdspp-home-service-text-learnmore">Learn more...<span> </span></span>
    </div>
    <img src="/cmdspp-ambulance" />
  </div>
  <div class="cmdspp-home-service-card">
    <div class="cmdspp-home-service-text">
      <h3>Social Workers</h3>
      <p>Onboard social workers and community professionals</p>
      <span class="cmdspp-home-service-text-learnmore">Learn more...<span> </span></span>
    </div>
    <img src="/cmdspp-socialworker" />
  </div>
</section>
<section class="cmdspp-home-ai-section">
  <h2>Every Decision, Powered by AI</h2>
  <p>We're dedicated to providing our members with the care they deserve.</p>
  <p>That's why we're focused on giving you the tools you need to deliver the highest quality service.</p>
</section>
<div class="row sectionBlockLayout text-start" style="display: none; flex-wrap: wrap; margin: 0px; min-height: auto; padding: 8px;">
  <div class="container" style="padding: 0px; display: flex; flex-wrap: wrap;"><div class="col-lg-12 columnBlockLayout" style="flex-grow: 1; display: flex; flex-direction: column; min-width: 250px;"></div></div>
</div>",
  "displayorder": 1,
  "enablerating": false,
  "enabletracking": false,
  "excludefromsearch": false,
  "feedbackpolicy": 756150005,
  "hiddenfromsitemap": false,
  "isroot": false,
  "pagetemplateid": "718ed8c8-9407-4620-adf3-832ec188887d",
  "partialurl": "/",
  "publishingstateid": "c7294317-419f-4724-8068-a91d5da8d92c",
  "rootwebpageid": "551cf2a7-4cb2-4424-8af7-3422ddbd968e",
  "sharedpageconfiguration": false,
  "summary": "<p>This is a sample landing page for you to start creating your website.</p>",
  "title": "Home",
  "parentpageid": null,
  "customcss": "/* HERO */



.cmdspp-home-hero-section {
    padding-top: 60px !important;
    padding: 132px 92px;
     background-image: url("/cmdspp_Langing_page_bg.png");
    background-repeat: no-repeat;
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    display: flex;
    height: 524px;
    
}

.cmdspp-home-hero-content {
    width: 700px;
    color: #ffffff;
}

.cmdspp-home-gov-badge {
    display: inline-block;
    padding: 8px 18px;
    border-radius: 20px;
    background: rgba(0, 61, 130, 0.45);
    border: 1px solid rgba(255,255,255,.15);
    font-size: 12px;
    font-weight: 400;
    letter-spacing: .5px;
    margin-bottom: 30px;
    img{
        margin-bottom: 3px;
        margin-right: 8px;
    }
}

.cmdspp-home-hero-content h1 {
    font-size: 58px;
    line-height: 1.1;
    font-weight: 400 !important;
    margin-bottom: 25px;
}

.cmdspp-home-hero-content p {
    width: 562px;
    font-size: 16px;
    font-weight: 400 !important;
    line-height: 1.6;
    margin-bottom: 28px;
    color: #ffffff;
}

.cmdspp-home-hero-buttons {
    display: flex;
    gap: 15px;
}

.cmdspp-home-btn{
    height: 46px;
    font-size: 14px;
    font-weight: 400 !important;
    line-height: 20px;
    border: none !important;
    box-shadow: none !important;

}

.cmdspp-home-btn-primary {
    display: inline-block;
    padding: 12px 25px;
    background: #0B3A6F;
    color: #FFFFFF;
    border-radius: 8px;
    text-decoration: none;
}

.cmdspp-home-btn-secondary {
    display: inline-block;
    padding: 12px 25px;
    background: #FFFFFF;
    color: #0B3A6F;
    border-radius: 8px;
    text-decoration: none;
}

/* SERVICES */

.cmdspp-home-services-section {
    max-width: 1200px;
    margin: -60px auto 33px;
    display: flex;
    justify-content: center;
    gap: 15px;
    flex-wrap: nowrap;
    position: relative;
    z-index: 10;
}

.cmdspp-home-service-card {
    width: 327px;
    height: 139px;
    background: #fff;
    border: 1px solid #d8e2ea;
    border-radius: 6px;
    padding: 12px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    box-shadow: 0 2px 8px rgba(0,0,0,.08);
}

.cmdspp-home-service-text {
    width: 48%;
    .cmdspp-home-service-text-learnmore {
        color: #1AA3A3;
        font-size: 14px;
        font-weight: 400 !important;
    }
}

.cmdspp-home-service-card h3 {
    font-size: 16px;
    font-weight: 400 !important;
    color: #0B3A6F;
    margin-bottom: 10px;
    margin-top: 0px !important;
}

.cmdspp-home-service-card p {
    font-size: 12px;
    line-height: 100%;
    margin-bottom: 10px;
    color: #060606;
}

.cmdspp-home-service-card img {
    width: 140px;
    height: 104px;
}


/* AI SECTION */
.cmdspp-home-ai-section {
    text-align: center;
    padding: 0px 20px 0px;
    margin-bottom: 29px !important;
}

.cmdspp-home-ai-section h2 {
    font-size: 42px;
    line-height: 63px;
    font-weight: 400 !important;
    margin-bottom: 16px;
    color: #292A30;
}

.cmdspp-home-ai-section p {
    color: #686677;
    font-size: 17px;
    line-height: 29px;
    margin-bottom: 0px !important;
    font-weight: 400 !important;
}

/* RESPONSIVE */

@media (max-width: 960px) {

    .cmdspp-home-hero-content {
        width: 100%;
    }

    .cmdspp-home-hero-content h1 {
        font-size: 42px;
    }

    .cmdspp-home-hero-content p {
        width: 100%;
    }

    .cmdspp-home-services-section {
        flex-direction: column;
        align-items: center;
    }

}",
  "customjavascript": "document.getElementById("cmdspp-home-btn-primary-id")
    .addEventListener("click", async function () {
        window.location.href =
            "/user-registration";

    });

document.getElementById("cmdspp-home-btn-secondary-id")
    .addEventListener("click", function () {
        window.location.href =
            "/signIn";

    });"
}
